from fastapi import Depends, FastAPI, HTTPException
from pydantic import BaseModel

app = FastAPI()

items = [
    {"id": 1, "name": "Microscope", "quantity": 4, "internal_note": "repair"},
]


class ItemOut(BaseModel):
    id: int
    name: str
    quantity: int


def get_items() -> list[dict[str, object]]:
    return items


@app.get("/items", response_model=list[ItemOut])
def list_items(records: list[dict[str, object]] = Depends(get_items)) -> list[dict[str, object]]:
    return records


@app.get("/items/{item_id}", response_model=ItemOut)
def read_item(item_id: int, records: list[dict[str, object]] = Depends(get_items)) -> dict[str, object]:
    for item in records:
        if item["id"] == item_id:
            return item
    raise HTTPException(status_code=404, detail="Item not found")
